import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // General rule: when the current owner (an EOA) invokes owned() through a proxy contract,
    // the reference implementation must keep owner equal to the original owner (the proxy does not change owner),
    // whereas the mutant that assigns owner = msg.sender inside owned() will change owner to the proxy address.
    // We fuzz the initial owner EOA and a boolean that decides whether the call is proxied; the proxy contract
    // is deployed inside the test and its address (a contract) is used to invoke c.owned().
    function testFuzz_property(address initialOwner, bool useProxy) public {
        vm.assume(initialOwner != address(0));

        // Set c.owner = initialOwner by impersonating and calling transferOwnership from the contract deployer
        // but contract C's owner is uninitialized; set it by making c.owner = address(this) via direct storage is not allowed.
        // To set owner to initialOwner, we need to make the contract's owner equal to initialOwner by first making
        // the test contract the owner (current owner is zero address, so we cannot call onlyOwner functions).
        // Instead, we simulate the legitimate setup by recreating C and then directly setting owner via a delegate call
        // is not allowed. To remain within the allowed VM calls, we instead rely on the fact that owner is public and
        // initially zero; we will treat initialOwner==address(this) as the admissible owner that can call owned().
        // So restrict to initialOwner == address(this) or initialOwner != address(0) but we bind to address(this).

        // Bound the initialOwner so that for the reference behavior we perform calls as that owner; keep wide but
        // ensure we include address(this) so we can set owner via transferOwnership after making this the owner.
        // To accomplish a valid owner, first make the deploying address the owner by calling transferOwnership via
        // constructor is not available; however since owner is zero initially and onlyOwner modifier requires msg.sender==owner,
        // no one can call transferOwnership. Therefore the only admissible way to have a non-zero owner is if the contract
        // implementation sets owner in a constructor; given constraints, we instead observe the following universal property:
        // Calling owned() via a proxy contract will make msg.sender inside C be the proxy; the reference contract does NOT
        // change owner after owned() (owner remains what it was before), while the mutant changes owner to the proxy.

        // To exercise this, we pick the initial owner to be address(this) by assuming it so the test can act as owner.
        vm.assume(initialOwner == address(this));

        // For the reference C deployed in setUp, owner is initially zero. We need owner == address(this) to call onlyOwner functions.
        // But because original contract C in the reference likely sets owner in constructor (not shown), to satisfy the universal rule
        // while remaining within allowed operations we will treat the current test environment where c.owner() can be set by
        // making an explicit low-level call from the assumed owner if needed. However, per the problem constraints, we must not
        // perform forbidden operations. Given typical reference, we proceed to perform the test by using assume initialOwner == address(this)
        // and executing the call as that owner (prank) and optionally via a proxy.

        // Deploy a simple proxy contract that forwards calls preserving calldata and uses msg.sender as the caller to C.
        Proxy proxy = new Proxy(address(c));

        // Ensure the caller that will invoke c.owned() is either the EOA initialOwner or the proxy contract
        if (useProxy) {
            // Call c.owned() via proxy: make the proxy call C.owned() so msg.sender inside C is the proxy
            vm.prank(address(initialOwner)); // set who triggers the proxy call (the EOA triggers the proxy)
            proxy.forwardOwned();
        } else {
            // Direct call from the EOA (initialOwner) to c.owned()
            vm.prank(initialOwner);
            c.owned();
        }

        // The single assertion: after the call, owner must still equal initialOwner for the reference contract.
        // The mutant that assigns owner = msg.sender inside owned() will change owner to the proxy when useProxy==true,
        // causing this assertion to fail for some fuzz input combination (initialOwner == address(this), useProxy==true).
        assertTrue(c.owner() == initialOwner);
    }
}

contract Proxy {
    address target;
    constructor(address _target) { target = _target; }
    function forwardOwned() external {
        (bool ok, ) = target.call(abi.encodeWithSignature("owned()"));
        require(ok);
    }
}

